/* ===== Swing trading C: indicators (with computed values) ===== */
/* indicator math used only to draw authentic example figures */
function sma(a, n) { return a.map((_, i) => i < n - 1 ? null : +(a.slice(i - n + 1, i + 1).reduce((s, v) => s + v, 0) / n).toFixed(3)); }
function ema(a, n) { const k = 2 / (n + 1); let e = a[0]; return a.map((v, i) => { e = i ? v * k + e * (1 - k) : v; return +e.toFixed(3); }); }
function rsi(a, n) {
  const out = a.map(() => null); let g = 0, l = 0;
  for (let i = 1; i < a.length; i++) {
    const d = a[i] - a[i - 1];
    if (i <= n) { g += Math.max(d, 0); l += Math.max(-d, 0); if (i === n) { g /= n; l /= n; out[i] = +(100 - 100 / (1 + g / (l || 1e-9))).toFixed(1); } }
    else { g = (g * (n - 1) + Math.max(d, 0)) / n; l = (l * (n - 1) + Math.max(-d, 0)) / n; out[i] = +(100 - 100 / (1 + g / (l || 1e-9))).toFixed(1); }
  }
  return out;
}
function macd(a) { const m = ema(a, 12).map((v, i) => +(v - ema(a, 26)[i]).toFixed(3)); const sig = ema(m, 9); return { m, sig, hist: m.map((v, i) => +(v - sig[i]).toFixed(3)) }; }
function closesOf(c) { return c.map(x => x[3]); }

STT('st-ma', { name: 'Moving averages', cat: 'stind',
  blurb: `A moving average smooths price into a single flowing line, revealing the trend and acting as dynamic support or resistance. The 20, 50 and 200-period averages are the most watched, and their crossovers are among the oldest trend signals.`,
  facts: [['Shows', 'trend direction, smoothed'], ['SMA', 'simple average (smoother, slower)'], ['EMA', 'weights recent price (faster)'], ['Key periods', '20, 50, 200']],
  cheat: [['SMA', 'Simple moving average — equal weight; smooth, lags more'], ['EMA', 'Exponential — recent-weighted; reacts faster'], ['20-period', 'Short-term trend; common pullback MA'], ['50-period', 'Medium-term trend'], ['200-period', 'Long-term trend; major bull/bear divider'], ['Price > rising MA', 'Uptrend bias'], ['Dynamic S/R', 'Price often bounces off a key MA'], ['Golden cross', '50 crosses above 200 → bullish (lagging)'], ['Death cross', '50 crosses below 200 → bearish (lagging)'], ['Slope', 'Direction of the MA = trend direction']],
  sections: [
    ['Price with moving averages', (() => { const c = trend(44, 40, 0.14, 1.1, 8); const cl = closesOf(c); return FIG(chart({ w: 560, h: 250, candles: c, lines: [{ data: ema(cl, 20), cls: 'stc-c1 stc-thin', label: '20 EMA' }, { data: sma(cl, 50), cls: 'stc-c2 stc-thin', label: '50 SMA' }] }), 'Moving averages smooth price. The faster 20-EMA hugs price and often acts as dynamic support in an uptrend; the slower 50-SMA defines the medium-term trend. Price above rising averages = uptrend bias.'); })()],
    ['SMA vs EMA, and which period', TBL(['Choice', 'Behaviour', 'Use'], [['SMA', 'Equal weight; smoother, slower to turn', 'Defining the broader trend (50, 200)'], ['EMA', 'Weights recent prices; turns faster', 'Timing pullbacks and faster signals (9, 20)'], ['20', 'Short-term', 'Pullback entries in a trend'], ['50', 'Medium-term', 'Trend filter; institutional watch level'], ['200', 'Long-term', 'The big bull/bear line; major support/resistance']]) + PP(`There is no "best" setting — shorter = more responsive but more false signals; longer = smoother but later. Pick a couple and stay consistent so you learn how your instrument behaves around them.`)],
    ['Three ways to use a moving average', UL([`<b>Trend filter:</b> only take longs when price is above a rising MA (e.g. the 50); only shorts when below a falling MA. This one rule keeps you on the right side of the trend.`, `<b>Dynamic support/resistance:</b> in a strong trend, price repeatedly pulls back <i>to</i> a key MA (often the 20-EMA) and bounces — a classic pullback-entry zone.`, `<b>Crossovers:</b> a faster MA crossing a slower one signals a trend shift. The <b>golden cross</b> (50 above 200) is bullish; the <b>death cross</b> (50 below 200) is bearish — but both <b>lag</b>, confirming trends rather than predicting them.`])],
    ['The lag trade-off', PP(`A moving average is built from <b>past</b> prices, so it always <b>lags</b>. That is the point — it filters noise — but it means MAs are late at turns: by the time a death cross prints, much of the fall may be done. Use MAs to <b>define and follow</b> trends and to find pullback zones, not to catch exact tops and bottoms. Faster settings reduce lag but whipsaw more; slower settings whipsaw less but lag more.`)]
  ],
  edge: [`MAs lag — crossovers like golden/death crosses confirm late and whipsaw badly in ranging markets.`, `In a sideways market, price crosses back and forth over the MA constantly — MA signals are for trends, not ranges.`, `There is no magic setting; curve-fitting the "perfect" period to past data rarely holds up live.`, `Using many MAs at once often just restates the trend — more lines ≠ more information.`, `Price touching an MA is a zone to watch, not an automatic trade — wait for a reaction.`],
  faq: [['SMA or EMA — which should I use?', PP(`Neither is universally better. The <b>EMA</b> weights recent prices so it reacts faster — handy for timing pullback entries (e.g. a 20-EMA) — while the <b>SMA</b> is smoother and better for defining the broader trend (50, 200). Many traders use an EMA for the fast line and an SMA for the slow line. The key is consistency: pick your settings and learn how your instrument trades around them.`)],
    ['What are the golden cross and death cross?', PP(`A <b>golden cross</b> is when the 50-period MA crosses <i>above</i> the 200 (bullish); a <b>death cross</b> is the 50 crossing <i>below</i> the 200 (bearish). They are widely watched long-term trend signals — but they <b>lag significantly</b> (they confirm a trend that is already well underway) and they whipsaw in choppy markets. Treat them as context/confirmation, not precise entry timing.`)],
    ['How do I use a moving average for pullback entries?', PP(`In a clear uptrend, price often pulls back to a key MA (commonly the 20-EMA) and resumes. Wait for price to reach the MA <b>and</b> show a reaction there — a bullish reversal candle or a hold of support at the MA — then enter with a stop just below the MA/swing low. The MA gives you a repeatable zone; the candle reaction gives you the trigger.`)]],
  qs: [SQ('What is the main trade-off of moving averages?', ['They predict exact tops', 'They lag because they are built from past prices', 'They only work on crypto', 'They remove all risk'], 1, 'MAs smooth noise but lag, so they confirm trends rather than predicting turns.'),
    SQ('A "golden cross" refers to…', ['Price hitting a round number', 'The 50-period MA crossing above the 200-period MA (bullish, lagging)', 'A candlestick pattern', 'The 20 crossing the 9'], 1, 'The 50-above-200 crossover is the golden cross — a lagging bullish trend signal.')]
});
DP('st-ma', {
  fu: [['What is a moving-average ribbon?', 'Several MAs of increasing length plotted together. When they fan out and align in order, the trend is strong; when they compress and tangle, the trend is weak or ranging. It is a visual trend-strength gauge, not a precise signal.'],
    ['Why is the 200-day MA so watched?', 'It represents roughly a year of trading and is a widely-followed line separating long-term bullish from bearish regimes. Many institutions and algorithms reference it, so reactions and crossovers around it draw real order flow — partly self-fulfilling.'],
    ['Can MAs be used as a trend filter for other signals?', 'Yes, and it is one of their best uses: only take long setups when price is above a rising MA and short setups when below a falling one. This single filter keeps you trading with the trend and removes many low-probability counter-trend trades.']],
  deep: [['Technique', 'Combine a fast EMA (pullback zone) with a slower SMA (trend filter): trade pullbacks to the fast MA only while price is above the rising slow MA, with a candle trigger and a stop below the MA.'],
    ['Failure mode', 'Trading MA crossovers in a range (constant whipsaw) or curve-fitting a "perfect" period that fails out of sample.'],
    ['In real charts', 'The 20/50/200 are the most-watched; strong trends ride the 20-EMA, pull back to the 50 in deeper corrections, and respect the 200 as a major line — reactions there are common.']],
  src: ['StockCharts ChartSchool: Moving Averages', 'https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-overlays/moving-averages'] });

STT('st-rsi', { name: 'RSI — the relative strength index', cat: 'stind',
  blurb: `RSI measures the speed and size of recent price moves on a 0–100 scale, flagging when a move may be overstretched. Beyond the classic overbought/oversold reading, its real power for swing traders is divergence — when momentum disagrees with price.`,
  facts: [['Scale', '0–100'], ['Overbought', '> 70'], ['Oversold', '< 30'], ['Best signal', 'divergence']],
  cheat: [['RSI > 70', 'Overbought — move stretched up (not an auto-sell)'], ['RSI < 30', 'Oversold — move stretched down (not an auto-buy)'], ['50 line', 'Momentum midpoint; above = bullish bias'], ['Bullish divergence', 'Price lower low, RSI higher low → turn up'], ['Bearish divergence', 'Price higher high, RSI lower high → turn down'], ['In a trend', 'RSI can stay overbought/oversold a long time'], ['In a range', 'Overbought/oversold works better'], ['Default period', '14'], ['Failure swing', 'RSI pattern confirming divergence'], ['Not standalone', 'Confirm with price/level']],
  sections: [
    ['Price and RSI, with divergence', (() => {
      const cl = [30, 31, 32.5, 33.8, 32.6, 31.4, 32.8, 34.6, 33.2, 31.8, 33.1, 35.2, 33.6, 32.1, 33.0, 34.2, 35.0, 34.0, 33.2, 34.4, 35.6, 34.6, 33.8, 34.9, 36.0];
      const r = rsi(cl, 14);
      return FIG(chart({ w: 560, h: 160, lines: [{ data: cl }], notes: [{ i: 11, p: 35.6, text: 'higher high', anchor: 'middle' }, { i: 20, p: 36.0, text: 'higher high', anchor: 'middle' }] }), 'Price makes higher highs…') +
        FIG(chart({ w: 560, h: 130, lines: [{ data: r }], min: 0, max: 100, yticks: 2, hlines: [{ p: 70, label: '70', cls: 'stc-res' }, { p: 30, label: '30', cls: 'stc-sup' }], notes: [{ i: 11, p: 72, text: 'lower high', anchor: 'middle' }, { i: 20, p: 64, text: 'lower high', anchor: 'middle' }] }), '…but RSI makes lower highs: bearish divergence. Momentum is fading even as price rises — a warning the up-move may be tiring.');
    })()],
    ['The three ways to read RSI', TBL(['Signal', 'What it means', 'Caveat'], [['Overbought (>70)', 'Up-move is stretched', 'In a strong uptrend RSI can stay >70 for a long time — not a sell by itself'], ['Oversold (<30)', 'Down-move is stretched', 'In a strong downtrend it can stay <30 — not a buy by itself'], ['50 line cross', 'Momentum shifting bullish/bearish', 'Lags; use as bias, not trigger'], ['Divergence', 'Momentum disagrees with price', 'The highest-value RSI signal; still needs price confirmation']]) + PP(`The beginner trap is treating overbought as "sell now." In a <b>trend</b>, overbought/oversold readings persist — the strongest moves are "overbought" the whole way up. Overbought/oversold works best in <b>ranges</b>; in trends, lean on divergence and the 50 line.`)],
    ['Divergence — RSI’s best signal', PP(`<b>Divergence</b> is when price and momentum disagree. <b>Bearish divergence:</b> price makes a <i>higher</i> high but RSI makes a <i>lower</i> high — each push up has less force behind it, warning the uptrend is tiring. <b>Bullish divergence:</b> price makes a <i>lower</i> low but RSI makes a <i>higher</i> low — selling is losing steam. Divergence is a <b>leading hint</b> of exhaustion, but it is not a timing tool on its own: trends can diverge for a while before turning. Use it to anticipate, then wait for price confirmation (a reversal candle, a level break).`)],
    ['Using RSI well', UL([`<b>Match it to the market:</b> overbought/oversold for ranges; divergence and the 50 line for trends.`, `<b>Confirm, don’t predict:</b> an oversold RSI <i>at support</i> with a bullish reversal candle is a setup; oversold alone is not.`, `<b>Default to period 14</b> and keep it consistent.`, `<b>Don’t fight strong trends</b> with RSI — "it’s overbought" has bankrupted many who shorted strong uptrends.`])]
  ],
  edge: [`"Overbought = sell" is the classic RSI mistake — in a strong trend RSI stays overbought while price keeps rising.`, `Divergence can persist for a long time before price turns — it warns, it does not time; wait for confirmation.`, `RSI in isolation is weak; it must be paired with price structure/levels.`, `Shortening the period makes RSI noisier (more false overbought/oversold); keep a sensible setting.`, `Overbought/oversold signals work far better in ranges than in trends — know which you are in.`],
  faq: [['Does overbought mean I should sell?', PP(`No — that is the most common RSI error. Overbought (>70) means the up-move is <i>stretched</i>, but in a strong uptrend RSI can stay overbought for weeks while price keeps climbing. Selling just because RSI is high means fighting the trend. Overbought/oversold is most useful in <b>ranges</b>; in trends, rely on <b>divergence</b> and the 50 line, and always require price confirmation before acting.`)],
    ['What is RSI divergence and why is it valuable?', PP(`Divergence is when RSI and price disagree: price makes a higher high while RSI makes a lower high (bearish), or price makes a lower low while RSI makes a higher low (bullish). It reveals that <b>momentum is fading</b> beneath the surface — each new price extreme has less force. That makes it a valuable early warning of a potential turn. But it is a <i>hint</i>, not a trigger: confirm with a reversal candle or a level break before trading it.`)],
    ['What RSI period should I use?', PP(`The default <b>14</b> is standard and what most traders watch, which is a good reason to keep it. Shorter periods make RSI more sensitive (more signals, more noise and false overbought/oversold); longer periods smooth it (fewer, slower signals). Change it only with a clear reason, and keep it consistent so you learn how your instrument behaves at the usual levels.`)]],
  qs: [SQ('In a strong uptrend, an RSI reading above 70 means…', ['Sell immediately', 'The move is stretched, but RSI can stay overbought while price keeps rising — not an auto-sell', 'The trend has ended', 'RSI is broken'], 1, 'Overbought persists in trends; it is not a standalone sell signal.'),
    SQ('Price makes a higher high while RSI makes a lower high. This is…', ['Bullish divergence', 'Bearish divergence — fading momentum, a warning for the uptrend', 'A golden cross', 'Meaningless'], 1, 'Price up, momentum down = bearish divergence, an early exhaustion warning (needs confirmation).')]
});
DP('st-rsi', {
  fu: [['What is an RSI “failure swing”?', 'A momentum pattern that confirms divergence without reference to price: e.g. (bearish) RSI goes above 70, pulls back, rallies to a lower high below 70, then breaks its intervening low. It is a more rules-based way to act on divergence/exhaustion.'],
    ['Why does overbought persist in trends?', 'RSI measures recent average gains vs losses; in a strong uptrend gains dominate for a long stretch, pinning RSI high. The indicator is doing its job (showing strong momentum) — the error is interpreting strong momentum as a reason to sell.'],
    ['How do you combine RSI with levels?', 'Best as confluence: an oversold RSI (or bullish divergence) occurring exactly at a tested support, with a reversal candle, is a far stronger long than any of those alone. RSI tells you momentum is stretched/turning; the level tells you where; the candle times it.']],
  deep: [['Technique', 'Use RSI contextually: range → fade overbought/oversold at the range edges; trend → watch the 50 line for bias and divergence for exhaustion, always confirmed by price.'],
    ['Failure mode', 'Shorting strong uptrends because RSI is "overbought," or trading divergence immediately without waiting for price to confirm the turn.'],
    ['In real charts', 'Divergence at a major level with a reversal candle is RSI’s highest-probability use; naked overbought/oversold in trends is a trap.']],
  src: ['StockCharts ChartSchool: Relative Strength Index (RSI)', 'https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-indicators/relative-strength-index-rsi'] });

STT('st-macd', { name: 'MACD — momentum & trend', cat: 'stind',
  blurb: `MACD blends trend and momentum: it tracks the gap between two moving averages, a signal line, and a histogram of their difference. Crossovers, the zero line, and MACD divergence give a flexible read on whether momentum is building or fading.`,
  facts: [['Built from', 'EMA(12) − EMA(26)'], ['Signal line', 'EMA(9) of MACD'], ['Histogram', 'MACD − signal'], ['Watch', 'crossovers, zero line, divergence']],
  cheat: [['MACD line', 'Fast EMA − slow EMA (12,26 default)'], ['Signal line', '9-EMA of the MACD line'], ['Histogram', 'MACD − signal; bars show momentum'], ['Bullish cross', 'MACD crosses above signal'], ['Bearish cross', 'MACD crosses below signal'], ['Zero line', 'Above = up-momentum; below = down'], ['Histogram shrinking', 'Momentum fading (early warning)'], ['Divergence', 'MACD vs price disagree → exhaustion'], ['Lags', 'MA-based, so late at turns'], ['Best', 'Trend/momentum confirmation, not ranges']],
  sections: [
    ['Price with the MACD panel', (() => { const c = trend(40, 30, 0.1, 1.0, 6); const cl = closesOf(c); const M = macd(cl); return FIG(chart({ w: 560, h: 170, candles: c }), 'Price trending up…') +
      FIG(chart({ w: 560, h: 140, lines: [{ data: M.m, cls: 'stc-c1 stc-thin', label: 'MACD' }, { data: M.sig, cls: 'stc-c2 stc-thin', label: 'signal' }], hlines: [{ p: 0, label: 'zero line', cls: '' }], yticks: 2 }), '…the MACD line (blue) above its signal (amber) and above zero confirms up-momentum. A cross below the signal, and then below zero, warns momentum is turning down.'); })()],
    ['The three parts and their signals', TBL(['Component', 'What it shows', 'Signal'], [['MACD line', 'Difference of fast & slow EMAs — momentum', 'Crossing the signal line'], ['Signal line', '9-EMA of MACD — a smoother reference', 'Crossovers with the MACD line'], ['Histogram', 'MACD − signal, as bars', 'Shrinking bars = momentum fading (early); growing = building'], ['Zero line', 'Whether fast EMA is above slow EMA', 'Above = bullish regime; below = bearish']]) + PP(`The <b>histogram</b> is the most forward-looking part: its bars shrink <i>before</i> the lines cross, giving an early hint that momentum is slowing. The <b>zero-line</b> cross is a slower, trend-regime signal.`)],
    ['How to use MACD', UL([`<b>Crossovers for timing:</b> a MACD line crossing above its signal is a bullish momentum signal (stronger when it happens above zero / with the trend).`, `<b>Zero line for regime:</b> above zero favours longs, below favours shorts — a trend filter.`, `<b>Histogram for early warning:</b> shrinking bars flag fading momentum before the cross.`, `<b>Divergence:</b> like RSI, MACD diverging from price warns of exhaustion.`, `<b>Confirm with trend/price</b> — MACD lags, so it is best as confirmation, not a standalone trigger.`])],
    ['MACD vs RSI', PP(`Both are momentum tools but answer different questions. <b>RSI</b> is <i>bounded</i> (0–100) and good at flagging <b>overstretched</b> conditions and divergence. <b>MACD</b> is <i>unbounded</i> and better at showing <b>trend momentum and shifts</b> (crossovers, zero line). They overlap, so using both adds less than beginners expect — pick the one that fits your style, or use one for momentum and a different <i>type</i> of tool (a moving average, volume) for confirmation, rather than stacking two momentum oscillators.`)]
  ],
  edge: [`MACD lags (it is built from EMAs) — crossovers confirm turns late and whipsaw in ranging markets.`, `Crossovers far from the zero line, against the trend, are low-quality; favour crosses with the trend.`, `Pairing MACD with RSI is redundant — both are momentum oscillators measuring similar things.`, `In a sideways market MACD crosses constantly with little follow-through; it is a trend/momentum tool.`, `Default 12/26/9 is standard; tweaking the settings to fit past data rarely helps live.`],
  faq: [['What do the MACD crossovers actually mean?', PP(`The <b>MACD line</b> is the gap between a fast and a slow EMA — a momentum measure. When it crosses <b>above</b> its signal line (a 9-EMA of itself), short-term momentum is turning up relative to the recent average (bullish); crossing <b>below</b> is bearish. Crossovers that occur <b>with the trend</b> and on the right side of the zero line are higher quality; counter-trend crosses whipsaw. Because MACD lags, use crosses as confirmation alongside price.`)],
    ['What is the histogram for?', PP(`The histogram plots MACD minus its signal as bars, visualising the <i>distance</i> between them. Its value is <b>early warning</b>: the bars start <b>shrinking</b> before the lines actually cross, hinting that momentum is slowing while price may still be rising. Growing bars show momentum building. Watching the histogram’s rhythm often flags a turn a few candles before the crossover does.`)],
    ['Should I use MACD and RSI together?', PP(`They are both momentum oscillators, so combining them is largely <b>redundant</b> — they tend to say the same thing and can give false confidence. It is usually better to pair a momentum tool (one of them) with a <i>different kind</i> of input — trend (a moving average), location (support/resistance), or participation (volume) — so each indicator adds genuinely new information rather than echoing the other.`)]],
  qs: [SQ('Which part of MACD gives the earliest hint that momentum is fading?', ['The zero line', 'The histogram (its bars shrink before the lines cross)', 'The signal line only', 'None'], 1, 'The histogram shrinks ahead of the crossover, flagging slowing momentum early.'),
    SQ('Why is pairing MACD with RSI often redundant?', ['They measure different things', 'Both are momentum oscillators measuring similar information', 'RSI is not an indicator', 'MACD only works on stocks'], 1, 'Two momentum oscillators echo each other; pairing different types of tools adds more.')]
});
DP('st-macd', {
  fu: [['What does a zero-line cross signal vs a signal-line cross?', 'A signal-line cross is a faster momentum signal (MACD vs its own average). A zero-line cross is slower and more structural — it means the fast EMA crossed the slow EMA, i.e. the trend regime flipped. Zero-line crosses lag more but filter noise; signal crosses are earlier but noisier.'],
    ['How is MACD divergence used?', 'Like RSI divergence: price makes a new extreme while MACD (or its histogram) makes a weaker one, warning of exhaustion. The histogram divergence is often the earliest. Confirm with price before trading it.'],
    ['Does changing 12/26/9 help?', 'Faster settings react sooner but whipsaw more; slower settings smooth but lag. The 12/26/9 default is what most traders watch, so signals around it attract order flow. Optimising to past data usually fails out of sample — consistency beats tuning.']],
  deep: [['Technique', 'Use MACD as a trend-momentum filter: favour signal-line crosses that occur with the trend and on the correct side of zero; watch the histogram for early fade; confirm with price.'],
    ['Failure mode', 'Trading every crossover in a range, stacking MACD with RSI for false confirmation, or acting on counter-trend crosses far from zero.'],
    ['In real charts', 'The most useful MACD reads are histogram momentum shifts and with-trend crossovers; zero-line position is a clean, simple regime filter.']],
  src: ['StockCharts ChartSchool: MACD', 'https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-indicators/moving-average-convergence-divergence-macd'] });

STT('st-bb', { name: 'Bollinger Bands & volatility', cat: 'stind',
  blurb: `Bollinger Bands wrap price in a volatility envelope: a moving average with bands set a couple of standard deviations above and below. They show when a market is quiet (bands squeeze) or stretched (price rides a band), supporting both breakout and mean-reversion ideas.`,
  facts: [['Middle', 'a moving average (often 20)'], ['Bands', '± ~2 standard deviations'], ['Squeeze', 'low volatility → big move coming'], ['Walk the band', 'strong trend']],
  cheat: [['Middle band', '20-period SMA (trend reference)'], ['Upper/lower band', 'Middle ± ~2 standard deviations'], ['Band width', 'Narrow = low volatility; wide = high'], ['Squeeze', 'Bands pinch → a volatility expansion is coming'], ['Walking the upper band', 'Strong uptrend (not an auto-sell)'], ['Tag the band in a range', 'Mean-reversion fade candidate'], ['Band = dynamic S/R', 'In ranges price oscillates band to band'], ['Breakout from squeeze', 'Trade the direction of expansion'], ['% B / bandwidth', 'Quantify position/width'], ['Not standalone', 'Confirm with price/volume']],
  sections: [
    ['Bollinger Bands on price', (() => { const c = trend(18, 50, 0.02, 0.35, 2).concat(trend(22, 50.3, 0.16, 0.9, 7)); const cl = closesOf(c); const mid = sma(cl, 20); const sd = cl.map((_, i) => { if (i < 19) return null; const w = cl.slice(i - 19, i + 1); const m = mid[i]; return Math.sqrt(w.reduce((s, v) => s + (v - m) ** 2, 0) / 20); }); return FIG(chart({ w: 560, h: 250, candles: c, lines: [{ data: mid, cls: 'stc-c1 stc-thin', label: '20 SMA' }, { data: mid.map((m, i) => m == null ? null : +(m + 2 * sd[i]).toFixed(2)), cls: 'stc-c2 stc-thin', dash: true }, { data: mid.map((m, i) => m == null ? null : +(m - 2 * sd[i]).toFixed(2)), cls: 'stc-c2 stc-thin', dash: true }] }), 'The bands pinch together when volatility is low (a "squeeze", left) — often before a big move — then expand as a trend takes off and price "walks" the upper band (right).'); })()],
    ['Two ways traders use the bands', TBL(['Idea', 'Setup', 'Context'], [['Squeeze breakout', 'Bands pinch tight → trade the breakout when they expand', 'Works out of low-volatility bases'], ['Mean reversion', 'Price tags the outer band → fade back toward the middle', 'Works in ranges, NOT strong trends'], ['Trend ride ("walking the band")', 'In a strong trend price hugs the band', 'Do not fade it — it is strength, not a reversal'], ['Middle band as S/R', 'Pullbacks to the middle (20-SMA) in a trend', 'Trend-following entries']]) + PP(`The critical nuance: tagging the upper band is <b>not</b> automatically a sell. In a range it is a fade; in a strong trend price <b>walks</b> the band higher for a long time. Read the context first.`)],
    ['The squeeze — volatility is cyclical', PP(`Volatility <b>contracts and expands in cycles</b>: quiet periods are followed by active ones and vice versa. When the bands <b>squeeze</b> (narrow sharply), the market is coiling and a larger move often follows — though the squeeze tells you a move is <i>likely</i>, not its <b>direction</b>. Traders wait for the bands to start expanding and take the breakout in that direction (confirmed by a decisive close and volume), with a stop on the other side of the base.`)],
    ['Using them well', UL([`<b>Match to regime:</b> mean-reversion (fade the bands) in ranges; trend-riding (don’t fade) in trends; squeeze-breakouts out of quiet bases.`, `<b>The middle band</b> is a 20-SMA — a trend reference and pullback zone.`, `<b>Confirm breakouts</b> with a close and volume; a poke outside a band is not a signal by itself.`, `<b>Bands are standard-deviation envelopes</b>, so ~95% of price stays inside with the default 2σ — closes <i>outside</i> are statistically notable but common in trends.`])]
  ],
  edge: [`Fading an upper-band tag in a strong uptrend ("it’s overbought") fails badly — price walks the band; fades are for ranges.`, `A squeeze predicts a move is likely, not its direction — don’t guess; trade the expansion.`, `A single poke outside a band is not a reversal signal; wait for price confirmation.`, `Default 20-period / 2σ is standard; curve-fitting the settings rarely helps.`, `Bands describe volatility, not direction — always combine with trend/structure.`],
  faq: [['Does price tagging the upper band mean sell?', PP(`Only in a <b>range</b>. In a range, tags of the outer bands are mean-reversion fade candidates (sell the upper, buy the lower, back toward the middle). But in a <b>strong trend</b>, price <b>"walks the band"</b> — it hugs the upper band for many candles while trending up, and fading it is fighting the trend. So the same event means opposite things depending on regime: identify range vs trend first, then decide.`)],
    ['What is a Bollinger squeeze and how do I trade it?', PP(`A <b>squeeze</b> is when the bands narrow sharply, reflecting unusually <b>low volatility</b> — the market coiling. Because volatility is cyclical, a squeeze often precedes a larger move, so it is a heads-up that a breakout may be near. It does <b>not</b> tell you the direction, so you wait for the bands to begin <b>expanding</b> and take the breakout in that direction (with a decisive close and, ideally, volume), placing a stop on the opposite side of the base.`)],
    ['How wide should the bands be?', PP(`The standard is a <b>20-period</b> middle with bands at <b>2 standard deviations</b>, which keeps roughly 95% of price inside in normal conditions — and it is what most traders watch. You can widen them (fewer touches, for calmer signals) or narrow them (more touches), but the default is well-tested and keeps you aligned with the crowd. As always, prefer consistency over tinkering.`)]],
  qs: [SQ('In a strong uptrend, price hugging the upper Bollinger Band is…', ['A clear sell signal', 'Strength ("walking the band") — fading it fights the trend', 'A squeeze', 'An error'], 1, 'Walking the band shows trend strength; fading the upper band is for ranges, not trends.'),
    SQ('A Bollinger squeeze indicates…', ['The exact direction of the next move', 'Low volatility that often precedes a larger move (direction unknown)', 'A guaranteed reversal', 'That price will stay flat forever'], 1, 'A squeeze signals a likely volatility expansion; you trade the breakout once direction reveals itself.')]
});
DP('st-bb', {
  fu: [['What are %B and Bandwidth?', '%B measures where price sits relative to the bands (0 = lower band, 1 = upper). Bandwidth measures how wide the bands are (volatility). %B helps quantify band position for rules; bandwidth helps identify squeezes (very low bandwidth) and expansions.'],
    ['Why is volatility said to be cyclical/mean-reverting?', 'Markets alternate between calm and active phases: tight ranges build up energy that releases in a trend or breakout, which then settles into a new range. Bands visualise this — squeezes (calm) tend to be followed by expansions (active), and vice versa.'],
    ['Can Bollinger Bands be combined with other tools?', 'Yes: a lower-band tag in a range that coincides with support and a bullish reversal candle is a stronger mean-reversion long than the band tag alone; a squeeze breakout confirmed by volume and a horizontal level is stronger than the squeeze alone.']],
  deep: [['Technique', 'Classify regime first: range → fade band tags toward the middle with a level + candle; trend → ride (don’t fade) and buy pullbacks to the middle band; base → trade the squeeze expansion with volume.'],
    ['Failure mode', 'Fading band tags in trends (walking the band), or guessing squeeze direction instead of waiting for the expansion.'],
    ['In real charts', 'Squeeze-then-expansion breakouts and range mean-reversion are the two staple Bollinger plays; the middle band doubles as a trend pullback zone.']],
  src: ['StockCharts ChartSchool: Bollinger Bands', 'https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-overlays/bollinger-bands'] });

STT('st-stoch-atr', { name: 'Stochastic & ATR', cat: 'stind',
  blurb: `Two more tools with distinct jobs: the stochastic oscillator times overbought/oversold turns within a range, and the Average True Range (ATR) measures volatility — which is how you size stops and targets to the market's real movement, not a guess.`,
  facts: [['Stochastic', 'momentum oscillator 0–100'], ['Stoch zones', '>80 overbought, <20 oversold'], ['ATR', 'average range per candle (volatility)'], ['ATR use', 'size stops & targets to volatility']],
  cheat: [['Stochastic %K/%D', 'Where close sits in the recent range; %D is the signal'], ['Stoch > 80', 'Overbought (best faded in ranges)'], ['Stoch < 20', 'Oversold (best faded in ranges)'], ['Stoch cross', '%K crossing %D in a zone = timing'], ['Stoch in trends', 'Stays pinned — like RSI, context matters'], ['ATR', 'Average true range — typical move per candle'], ['ATR for stops', 'Stop = entry − (1.5–3 × ATR)'], ['ATR for targets', 'Scale targets to volatility'], ['Rising ATR', 'Volatility increasing (wider stops needed)'], ['ATR ≠ direction', 'It measures size of moves, not which way']],
  sections: [
    ['Stochastic: timing turns in a range', (() => {
      const cl = [20, 20.6, 21.2, 20.8, 20.2, 20.7, 21.3, 20.9, 20.3, 20.8, 21.4, 20.95, 20.35, 20.9, 21.5];
      // simple %K over period 5
      const K = cl.map((v, i) => { if (i < 4) return null; const w = cl.slice(i - 4, i + 1); const lo = Math.min(...w), hi = Math.max(...w); return +(100 * (v - lo) / ((hi - lo) || 1e-9)).toFixed(1); });
      return FIG(chart({ w: 560, h: 150, lines: [{ data: cl }], hlines: [{ p: 21.4, label: 'range top', cls: 'stc-res' }, { p: 20.1, label: 'range bottom', cls: 'stc-sup' }] }), 'Price oscillating in a range…') +
        FIG(chart({ w: 560, h: 120, lines: [{ data: K, cls: 'stc-c3 stc-thin' }], min: 0, max: 100, yticks: 2, hlines: [{ p: 80, label: '80', cls: 'stc-res' }, { p: 20, label: '20', cls: 'stc-sup' }] }), '…the stochastic swings between overbought (>80, fade for shorts) and oversold (<20, fade for longs) — a range-timing tool.');
    })()],
    ['ATR: sizing stops to volatility', (() => { const c = trend(30, 40, 0.08, 1.3, 7); return FIG(chart({ w: 560, h: 230, candles: c, marks: [{ i: 20, p: c[20][3], type: 'buy', label: 'entry' }, { i: 0, p: c[20][3] - 4.2, type: 'stop', label: 'stop ≈ entry − 2×ATR' }] }), 'ATR measures the typical candle range. Placing the stop a multiple of ATR away (e.g. 2×ATR) gives the trade room to breathe in that instrument’s normal volatility, instead of using an arbitrary fixed distance.'); })()],
    ['Stochastic vs RSI (both oscillators)', PP(`The <b>stochastic</b> asks "where is the close within the recent high-low range?" — it is quick and good at <b>timing turns in ranges</b> (the %K/%D crossover in the overbought/oversold zone). Like RSI, it <b>stays pinned</b> in strong trends, so it is a range tool, not a trend tool. RSI and stochastic are both momentum oscillators; using both is redundant — pick one. The stochastic is a bit faster/noisier; RSI is a bit smoother.`)],
    ['Why ATR is special — it measures risk, not direction', PP(`<b>ATR (Average True Range)</b> is not a buy/sell signal; it tells you the <b>typical size of a candle’s move</b>. That is exactly what you need to size a <b>stop</b>: a stop placed 2×ATR away sits beyond normal noise, so you are not shaken out by a routine wiggle — and it adapts automatically as volatility changes (wider stops in volatile conditions, tighter in calm ones). ATR is one of the most useful tools in the whole course because it ties your risk to the market’s real behaviour. It is used throughout the stop-loss and position-sizing units.`)]
  ],
  edge: [`Stochastic (like RSI) stays overbought/oversold in strong trends — fading it works in ranges, not trends.`, `Using both stochastic and RSI is redundant; they measure similar momentum.`, `ATR gives no direction — it is a volatility/risk tool, not a signal.`, `A fixed-pip/dollar stop ignores volatility; ATR-based stops adapt to the instrument and conditions.`, `Very short stochastic settings are extremely noisy; keep sensible defaults.`],
  faq: [['When is the stochastic oscillator most useful?', PP(`In <b>ranging</b> markets, for timing turns at the range edges: when the stochastic is overbought (>80) near resistance, look to fade for a short; oversold (<20) near support, look to fade for a long, using the %K/%D crossover for timing. In strong <b>trends</b> it pins at the extremes (like RSI), so it misleads — it is a range tool. Don’t use it to fight trends.`)],
    ['How do I use ATR to set a stop loss?', PP(`Place your stop a <b>multiple of ATR</b> beyond your entry — commonly <b>1.5× to 3× ATR</b>, depending on how much room the setup needs. Because ATR reflects the instrument’s <i>current</i> typical movement, this keeps your stop outside normal noise and adapts automatically: wider in volatile markets, tighter in calm ones. Then size the position so that ATR-based distance equals your fixed risk per trade (see the position-sizing unit).`)],
    ['Do I need both stochastic and RSI?', PP(`No — they are both momentum oscillators and largely redundant. Choose one (stochastic is faster and better in ranges; RSI is smoother and widely used), and spend your "second indicator" slot on something that adds <i>different</i> information: a moving average for trend, ATR for volatility/risk, or volume for participation. Combining two oscillators gives false confirmation, not more insight.`)]],
  qs: [SQ('What does ATR measure, and what is it mainly used for?', ['Direction; for entries', 'The typical size of price moves (volatility); for sizing stops and targets', 'Volume; for breakouts', 'Trend; for crossovers'], 1, 'ATR is a volatility measure used to size stops/targets to the market’s real movement, not direction.'),
    SQ('The stochastic oscillator works best in…', ['Strong trends', 'Ranging markets (timing turns at the edges)', 'Only crypto', 'Gaps'], 1, 'Like RSI, stochastic overbought/oversold is reliable in ranges but pins in trends.')]
});
DP('st-stoch-atr', {
  fu: [['What is the difference between fast and slow stochastic?', 'Fast stochastic (%K and its %D) is twitchy; slow stochastic smooths %K before computing %D, giving fewer false signals. Most traders use the slow version for steadier readings; both are range-timing tools.'],
    ['How is “true range” different from just high − low?', 'True range is the greatest of: current high − low, |high − previous close|, and |low − previous close|. It accounts for gaps (overnight moves), so ATR captures real volatility including gap risk — important for swing traders holding overnight.'],
    ['Can ATR trail a stop?', 'Yes — a "chandelier" or ATR trailing stop sits a set number of ATRs below the highest high since entry (for a long), ratcheting up as price rises and giving the trend room while locking in gains. It adapts the trail to current volatility.']],
  deep: [['Technique', 'Use the stochastic only to time range reversals at the edges; use ATR everywhere for risk — stop distance, position size, and trailing — so your risk scales with real volatility.'],
    ['Failure mode', 'Fading stochastic in trends, stacking it with RSI, or using fixed stops that ignore volatility (too tight in volatile markets, too loose in calm ones).'],
    ['In real charts', 'ATR-based stops and position sizing are a hallmark of disciplined traders; the stochastic is a useful but situational range tool.']],
  src: ['StockCharts ChartSchool: Average True Range (ATR)', 'https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-indicators/average-true-range-atr'] });

STT('st-vol-ind', { name: 'Volume indicators: OBV, VWAP & relative volume', cat: 'stind',
  blurb: `Raw volume bars are useful, but volume indicators distil them. On-Balance Volume tracks whether volume is flowing into or out of an asset, VWAP shows the volume-weighted average price institutions watch, and relative volume tells you if today's activity is unusual.`,
  facts: [['OBV', 'cumulative up/down volume'], ['VWAP', 'volume-weighted average price'], ['RVOL', 'today’s volume vs average'], ['Use', 'confirm moves & spot interest']],
  cheat: [['OBV', 'Adds volume on up days, subtracts on down days'], ['OBV trend', 'Rising OBV confirms buying pressure'], ['OBV divergence', 'OBV vs price disagree → warning'], ['VWAP', 'Average price weighted by volume (intraday reference)'], ['Above VWAP', 'Buyers in control (bullish bias)'], ['VWAP as S/R', 'Price often reacts to VWAP'], ['Relative volume (RVOL)', 'Today’s volume ÷ average — unusual activity'], ['High RVOL', 'Something is happening — stronger moves'], ['Low RVOL', 'Quiet — breakouts less reliable'], ['Confirm, not predict', 'Volume tools support price']],
  sections: [
    ['On-Balance Volume confirming a trend', (() => { const c = trend(30, 20, 0.12, 0.9, 4); const cl = closesOf(c); let obv = 0; const o = cl.map((v, i) => { if (i) obv += (v > cl[i - 1] ? 1 : v < cl[i - 1] ? -1 : 0) * (8 + (i % 4)); return obv; }); return FIG(chart({ w: 560, h: 170, candles: c }), 'Price rising…') + FIG(chart({ w: 560, h: 110, lines: [{ data: o, cls: 'stc-c4 stc-thin', label: 'OBV' }], yticks: 2 }), '…and OBV rising with it confirms that volume is flowing in behind the move. If OBV flattened or fell while price rose, that divergence would warn the rally lacks participation.'); })()],
    ['The three tools and their jobs', TBL(['Tool', 'What it shows', 'Best use'], [['OBV', 'Cumulative volume flow (buying vs selling pressure)', 'Confirm trends; spot divergence vs price'], ['VWAP', 'The volume-weighted average price for the session', 'Intraday fair-value and dynamic S/R; bias above/below'], ['Relative volume (RVOL)', 'How today’s volume compares to normal', 'Filter: trade breakouts/setups when RVOL is elevated']]) + PP(`All three answer "is there real participation behind this move?" — the question that separates a genuine breakout from a fakeout.`)],
    ['VWAP — the institutional reference', PP(`<b>VWAP</b> is the average price weighted by volume over a period (usually the trading day). Large institutions use it to judge whether they are getting a good fill, so price frequently <b>reacts to VWAP</b> as support/resistance, and being <b>above</b> VWAP is a simple bullish bias (buyers in control) while below is bearish. It is primarily an <b>intraday</b> tool, so for daily-chart swing trading it matters most on the lower timeframes you might use to fine-tune an entry.`)],
    ['Relative volume as a filter', PP(`<b>Relative volume (RVOL)</b> compares current volume to the typical volume for that time — e.g. 3× RVOL means three times the usual activity. It is a powerful <b>filter</b>: breakouts and setups on <b>high</b> RVOL have real participation and follow through more often; the same setup on <b>low</b> RVOL is likely to fizzle. Many traders simply refuse breakout trades unless volume is clearly elevated.`)]
  ],
  edge: [`Volume indicators confirm, they don’t predict — OBV rising doesn’t guarantee higher prices, it describes participation.`, `VWAP is mainly an intraday tool; its relevance fades on higher-timeframe swing charts.`, `Forex has no centralised volume, so OBV/RVOL there rely on tick-volume proxies — interpret with care.`, `A single high-volume candle can be a climax (reversal) or a breakout (continuation); context decides.`, `Don’t stack many volume tools — OBV, VWAP and RVOL overlap; pick what fits your process.`],
  faq: [['What is OBV good for?', PP(`On-Balance Volume adds a period’s volume when price closes up and subtracts it when price closes down, building a running total of <b>volume flow</b>. A <b>rising OBV</b> alongside rising price confirms that buying pressure is real; <b>OBV divergence</b> (price makes a new high but OBV does not) warns the move lacks participation and may be tiring. Like other volume tools, it <b>confirms</b> price rather than leading it.`)],
    ['Is VWAP useful for swing trading?', PP(`VWAP is mainly an <b>intraday</b> reference — it resets each session and is heavily used by day traders and institutions for fair-value fills and dynamic support/resistance. For a swing trader working off the daily chart it is less central, but it can help <b>time an entry</b> on the lower timeframe (e.g. buying a daily pullback when price reclaims the intraday VWAP). Anchored VWAP (from a significant event) can also act as longer-term S/R.`)],
    ['How do I use relative volume?', PP(`Treat it as a <b>go/no-go filter</b> for breakouts and setups: elevated RVOL means unusual participation, so moves are more likely to be real and to follow through; low RVOL means a quiet tape where breakouts often fail. A simple, effective rule is to only take breakout entries when volume is clearly above its recent average — it filters out many fakeouts with one check.`)]],
  qs: [SQ('What does On-Balance Volume (OBV) primarily help you do?', ['Predict exact price targets', 'Confirm whether volume flow supports a price move, and spot divergence', 'Set stop losses', 'Measure volatility'], 1, 'OBV tracks cumulative volume flow to confirm moves and flag divergence.'),
    SQ('A breakout on high relative volume (RVOL) versus low RVOL is…', ['Less reliable', 'More reliable — real participation is behind it', 'Identical', 'Always a fakeout'], 1, 'Elevated RVOL means unusual participation, making breakouts more likely to follow through.')]
});
DP('st-vol-ind', {
  fu: [['What is anchored VWAP?', 'A VWAP started from a specific significant bar (an earnings date, a swing high/low, a major breakout) rather than the session open. It shows the average price paid since that event and often acts as meaningful support/resistance on higher timeframes — useful for swing traders.'],
    ['Why does OBV use closing direction rather than the candle’s range?', 'OBV is a simple cumulative measure: it assumes a higher close means net buying (add all the period’s volume) and a lower close means net selling (subtract it). It is crude but effective at showing the broad direction of volume flow and divergences, which is its purpose.'],
    ['How is relative volume computed?', 'Current volume divided by the average volume for the same point in time over a lookback (e.g. the 20-day average volume). RVOL of 2 means twice the normal activity. It normalises volume so you can judge "unusual" regardless of the instrument’s baseline.']],
  deep: [['Technique', 'Use RVOL as a breakout filter, OBV to confirm trend participation and flag divergence, and (anchored) VWAP as a reference level — each adds a different slice of the "is there real interest?" question.'],
    ['Failure mode', 'Treating volume tools as predictive, applying VWAP to the wrong (too-high) timeframe, or trusting volume figures in markets without centralised volume.'],
    ['In real charts', 'High-RVOL breakouts with rising OBV are high-quality; divergence between price and OBV frequently precedes stalls, mirroring momentum divergence.']],
  src: ['StockCharts ChartSchool: On Balance Volume (OBV)', 'https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-indicators/on-balance-volume-obv'] });

STT('st-combine', { name: 'Combining indicators & divergence', cat: 'stind',
  blurb: `More indicators is not more insight. The skill is combining a few tools that each add different information — trend, momentum, volatility, volume — so they confirm rather than echo each other, and knowing that divergence is a hint, never a standalone trigger.`,
  facts: [['Goal', 'confluence, not clutter'], ['Combine', 'different types, not duplicates'], ['Divergence', 'a hint, needs confirmation'], ['Danger', 'over-optimising to the past']],
  cheat: [['One per job', 'Trend + momentum + volatility/volume — not two of each'], ['Redundant pairs', 'RSI+Stochastic, MACD+RSI (all momentum)'], ['Good combos', 'MA (trend) + RSI (momentum) + volume'], ['Confluence', 'Signals agree at one place = stronger'], ['Confirmation', 'Price action triggers; indicators support'], ['Divergence', 'Early warning, not entry by itself'], ['Fewer is better', '2–3 tools you understand deeply'], ['Over-optimisation', 'Tuning to past data fails live'], ['Indicators lag', 'Price leads; indicators describe'], ['Keep it simple', 'A clean process beats a cluttered one']],
  sections: [
    ['The trap: redundant indicators', PP(`Beginners stack five indicators and feel more confident — but RSI, stochastic and MACD are <b>all momentum oscillators</b>. When they agree, you have one piece of information shown three ways, not three confirmations. Worse, when you have enough indicators, <b>some will always agree</b> with whatever you want to do, feeding bias. The fix: use <b>one tool per job</b>.`)],
    ['A clean indicator stack', TBL(['Job', 'Pick one', 'Adds'], [['Trend / direction', 'A moving average (e.g. 50)', 'Which way to lean, and a pullback zone'], ['Momentum', 'RSI or MACD (not both)', 'Whether the move has force, and divergence'], ['Volatility / risk', 'ATR', 'How far to place stops/targets'], ['Participation', 'Volume / RVOL', 'Whether a breakout is real']]) + PP(`Each row answers a <b>different question</b>, so together they form a genuine picture: trade with the MA’s trend, when momentum agrees, confirmed by volume, with risk sized by ATR. That is confluence — and price action (levels, candles) remains the trigger.`)],
    ['How confluence actually helps', FIG((() => { const c = trend(30, 40, 0.0, 0.8, 3).concat(trend(8, 40, -0.3, 0.5, 11)); const cl = closesOf(c); return chart({ w: 560, h: 240, candles: c, lines: [{ data: ema(cl, 20), cls: 'stc-c1 stc-thin', label: '20 EMA' }], hlines: [{ p: 39.2, label: 'support', cls: 'stc-sup' }], marks: [{ i: 36, p: 39.5, type: 'buy', label: 'confluence: support + EMA + reversal candle' }] }); })(), 'A high-quality entry is where several reasons stack: price pulls back to support that coincides with the rising 20-EMA, momentum is turning up, volume confirms, and a bullish reversal candle triggers. Any one alone is weak; together they are an "A+" setup.')],
    ['Divergence: a hint, not a trigger', PP(`Divergence (price and momentum disagreeing) is one of the most <b>useful</b> indicator readings — it reveals weakening force beneath the surface before price turns. But it is a <b>leading hint</b>, not an entry: strong trends can diverge for a long time before reversing, and trading divergence blindly means repeatedly fighting trends too early. Use it to raise your alertness and to <b>confirm</b> a reversal you are already seeing in price (a candle, a level break, a structure break) — never as the sole reason to trade.`)]
  ],
  edge: [`Stacking multiple momentum oscillators (RSI+Stoch+MACD) is false confirmation — they echo each other and feed bias.`, `With enough indicators, some will always support any decision — more tools can mean worse discipline.`, `Over-optimising settings to fit past data ("curve fitting") almost never survives live trading.`, `Divergence alone is a trap — it can persist; wait for price to confirm.`, `Indicators lag price; if an indicator and clear price action disagree, respect price.`],
  faq: [['How many indicators should I use?', PP(`Few — typically <b>two or three</b> that you understand deeply, each doing a <i>different</i> job: one for trend (a moving average), one for momentum (RSI or MACD), and ATR for risk, with volume as confirmation. Adding more of the <b>same type</b> (another oscillator) gives redundancy and false confidence, not insight. A clean, simple process you can execute consistently beats a cluttered chart you second-guess.`)],
    ['Which indicator combinations are redundant?', PP(`Any that measure the <b>same thing</b>: RSI + stochastic (both range-momentum oscillators), MACD + RSI (both momentum), two moving averages used as separate "signals". Good combinations pair <b>different</b> dimensions — trend + momentum + volume + volatility — so each adds new information. The test: if two indicators almost always agree, you only need one.`)],
    ['Can I trade on divergence alone?', PP(`No. Divergence is a valuable <b>early-warning hint</b> that momentum is fading, but by itself it is unreliable for timing — trends routinely diverge for many candles before reversing, and acting early means fighting the trend repeatedly. Treat divergence as a reason to <b>watch closely</b>, then enter only when <b>price confirms</b> the turn (a reversal candle, a broken level or structure). Divergence sharpens your anticipation; price action pulls the trigger.`)]],
  qs: [SQ('Why is combining RSI, stochastic and MACD generally a mistake?', ['They are too simple', 'They are all momentum oscillators — redundant, giving false confirmation', 'They only work on stocks', 'They are too slow'], 1, 'They measure similar momentum, so agreement is one input shown three ways, feeding bias.'),
    SQ('How should divergence be used?', ['As a standalone entry trigger', 'As an early warning that needs price confirmation before trading', 'Ignored entirely', 'Only on the 1-minute chart'], 1, 'Divergence hints at fading momentum; wait for price to confirm the turn before acting.')]
});
DP('st-combine', {
  fu: [['What is “confluence” in one sentence?', 'Several independent reasons — trend, level, momentum, volume, candle — pointing to the same trade at the same place, which raises probability far above any single signal.'],
    ['What is curve fitting / over-optimisation?', 'Tuning indicator settings or rules until they look perfect on past data. The result fits historical noise, not a real edge, and typically fails on new data. Favour robust, standard settings tested across many instruments and periods over a "perfect" backtest.'],
    ['If indicators lag, why use them at all?', 'They objectively summarise information price action alone can blur — trend direction, momentum strength, volatility, participation — and impose discipline (rules over feelings). The key is to let price action lead and use indicators to confirm and to size risk, not to predict.']],
  deep: [['Technique', 'Build a minimal stack (trend MA + one momentum tool + ATR + volume), define how they must align, and require a price-action trigger. Grade setups by how much confluence is present.'],
    ['Failure mode', 'Indicator soup (many redundant tools), curve-fitted settings, and trading divergence or any single indicator in isolation.'],
    ['In real practice', 'Experienced traders use few indicators and lean heavily on price, level and volume; the edge is in selective, high-confluence setups and risk control, not in the indicators themselves.']],
  src: ['Investopedia: Combining Technical Indicators', 'https://www.investopedia.com/articles/active-trading/011415/best-technical-indicators-swing-trading.asp'] });
